CREATE POLICY "agent_knowledge_bases_read" ON "agent_knowledge_bases" AS PERMISSIVE FOR SELECT TO public USING ("agent_knowledge_bases"."organization_id" = nullif(current_setting('app.organization_id', true), '')::uuid AND EXISTS (SELECT 1 FROM agents a WHERE a.id = "agent_knowledge_bases"."agent_id" AND a.organization_id = "agent_knowledge_bases"."organization_id"));--> statement-breakpoint
CREATE POLICY "agent_knowledge_bases_insert" ON "agent_knowledge_bases" AS PERMISSIVE FOR INSERT TO public WITH CHECK ("agent_knowledge_bases"."organization_id" = nullif(current_setting('app.organization_id', true), '')::uuid AND "agent_knowledge_bases"."created_by" = nullif(current_setting('app.user_id', true), '')::uuid AND EXISTS (SELECT 1 FROM agents a WHERE a.id = "agent_knowledge_bases"."agent_id" AND a.organization_id = "agent_knowledge_bases"."organization_id" AND (a.created_by = nullif(current_setting('app.user_id', true), '')::uuid OR snowfall_is_admin() OR snowfall_access('agent', a.id) = 'edit')) AND snowfall_knowledge_can_edit("agent_knowledge_bases"."base_id"));--> statement-breakpoint
CREATE POLICY "agent_knowledge_bases_update" ON "agent_knowledge_bases" AS PERMISSIVE FOR UPDATE TO public USING ("agent_knowledge_bases"."organization_id" = nullif(current_setting('app.organization_id', true), '')::uuid AND EXISTS (SELECT 1 FROM agents a WHERE a.id = "agent_knowledge_bases"."agent_id" AND a.organization_id = "agent_knowledge_bases"."organization_id" AND (a.created_by = nullif(current_setting('app.user_id', true), '')::uuid OR snowfall_is_admin() OR snowfall_access('agent', a.id) = 'edit'))) WITH CHECK ("agent_knowledge_bases"."organization_id" = nullif(current_setting('app.organization_id', true), '')::uuid);--> statement-breakpoint
CREATE POLICY "agent_knowledge_bases_delete" ON "agent_knowledge_bases" AS PERMISSIVE FOR DELETE TO public USING ("agent_knowledge_bases"."organization_id" = nullif(current_setting('app.organization_id', true), '')::uuid AND EXISTS (SELECT 1 FROM agents a WHERE a.id = "agent_knowledge_bases"."agent_id" AND a.organization_id = "agent_knowledge_bases"."organization_id" AND (a.created_by = nullif(current_setting('app.user_id', true), '')::uuid OR snowfall_is_admin() OR snowfall_access('agent', a.id) = 'edit')));--> statement-breakpoint
CREATE POLICY "knowledge_bases_read" ON "knowledge_bases" AS PERMISSIVE FOR SELECT TO public USING ("knowledge_bases"."organization_id" = nullif(current_setting('app.organization_id', true), '')::uuid AND (nullif(current_setting('app.user_id', true), '')::uuid IS NULL OR "knowledge_bases"."created_by" = nullif(current_setting('app.user_id', true), '')::uuid OR snowfall_access('knowledge_base', "knowledge_bases"."id") IS NOT NULL
        OR EXISTS (SELECT 1 FROM agent_knowledge_bases l JOIN agents a ON a.id = l.agent_id AND a.organization_id = l.organization_id WHERE l.base_id = "knowledge_bases"."id")
        OR EXISTS (SELECT 1 FROM project_knowledge_bases l WHERE l.base_id = "knowledge_bases"."id" AND l.user_id = nullif(current_setting('app.user_id', true), '')::uuid)));--> statement-breakpoint
